SW.prof=()=>`<div class="cd"><b>الملف الشخصي</b>${fl('اسمك','s0',D.s.user,'text','oninput="ss(\'user\',this.value)"')}${im2('photo','الصورة')}</div>`;
SW.org=()=>{const s=D.s;return `<div class="cd"><b>بيانات المؤسسة</b>${fl('اسم المؤسسة','s1',s.name,'text','oninput="ss(\'name\',this.value)"')}${fl('الهاتف','s2',s.ph,'tel','oninput="ss(\'ph\',this.value)"')}${fl('العنوان','s3',s.addr,'text','oninput="ss(\'addr\',this.value)"')}${fl('بيانات إضافية في الفاتورة','s4',s.inf,'text','oninput="ss(\'inf\',this.value)"')}</div><div class="cd"><b>الشعار والختم</b>${im2('logo','الشعار')}${im2('stamp','الختم / الاعتماد')}</div>`};
SW.look=()=>{const s=D.s;return `<div class="cd"><b>اسم النظام</b>${fl('الاسم الظاهر أعلى الشاشة','s7',s.sys||s.name,'text','oninput="ss(\'sys\',this.value)"')}</div><div class="cd"><b>الخط</b>${FONTS.map(x=>`<div class="li" style="font-family:'${x}';border:2px solid ${(s.font||'Cairo')==x?'var(--p)':'var(--b)'}" onclick="ss('font','${x}');draw()"><span>${x}</span><span>أسامة العزي للتجارة ١٢٣٤٥</span></div>`).join('')}</div><div class="cd"><b>الوضع</b><div class="row">${[['light','فاتح'],['dark','داكن'],['auto','تلقائي']].map(([k,l])=>`<button class="${(s.mode||'light')==k?'':'s'}" onclick="ss('mode','${k}');draw()">${l}</button>`).join('')}</div></div><div class="cd"><b>الألوان</b><div class="row"><div><label>لون النظام</label><input type="color" value="${s.c1}" oninput="ss('c1',this.value)"></div><div><label>لون التمييز</label><input type="color" value="${s.c2}" oninput="ss('c2',this.value)"></div></div></div>`};
SW.invs=()=>{const s=D.s;return `<div class="cd"><b>إعدادات الفواتير</b>${fl('رقم الفاتورة التالي','s6',s.inv,'number','oninput="ss(\'inv\',+this.value)"')}${fl('ملاحظة أسفل الفاتورة','s5',s.note,'text','oninput="ss(\'note\',this.value)"')}<label>لون الفاتورة</label><input type="color" value="${s.c3}" oninput="ss('c3',this.value)"></div><p class="m">الشعار والختم وبيانات المؤسسة تظهر تلقائيًا في الفاتورة.</p>`};
SW.lists=()=>lb('pc')+lb('cc')+lb('un');
SW.alr=()=>{const s=D.s;return `<div class="cd"><b>التنبيهات</b><div class="row"><button class="${s.al?'':'s'}" onclick="ss('al',1);draw()">مفعّلة</button><button class="${s.al?'s':''}" onclick="ss('al',0);draw()">متوقفة</button></div>${fl('نبّهني عندما يقل رصيد الصنف عن','s8',s.minq,'number','oninput="ss(\'minq\',+this.value)"')}${fl('نبّهني بالعميل المتأخر بعد (يوم)','s9',s.due,'number','oninput="ss(\'due\',+this.value)"')}</div>`};
SW.bk=()=>`<div class="cd"><b>نسخة احتياطية</b><p class="m">اضغط إنشاء ثم انسخ النص واحفظه. للاستعادة الصق النص هنا.</p><div class="row"><button onclick="mkBk()">إنشاء ونسخ النسخة</button><button class="d" onclick="restore()">استعادة</button></div><textarea id="bk" rows="5"></textarea></div><div class="cd"><b>البدء من جديد</b><p class="m">يمسح المنتجات والعملاء والموردين والفواتير والحركات ويبقي الإعدادات والفئات. استخدمه بعد التجربة وقبل العمل الحقيقي.</p><button class="d" onclick="wipe()">مسح بيانات التجربة</button></div>`;
function wipe(){if(!confirm('سيتم مسح جميع المنتجات والعملاء والموردين والفواتير والحركات. الإعدادات والفئات تبقى. متابعة؟')||!confirm('تأكيد أخير: لا يمكن التراجع. هل أخذت نسخة احتياطية؟'))return;['P','C','S','M','I','R','SI','SP','T','L','X'].forEach(k=>D[k]=[]);Object.assign(D.s,{inv:1,rc:1,rcp:1,sc:1});sv();nv('home')}
const sha=async t=>{try{const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode('oazz|'+t));return[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}catch(e){return 'p|'+t}};
function lock(){if(!D.s.pin)return;$('#lk').innerHTML=`<div class="cd" style="width:100%;max-width:340px;text-align:center"><h3>🔒 ${E(D.s.sys||D.s.name)}</h3><input id="pw" type="password" inputmode="numeric" placeholder="رمز الدخول" onkeydown="if(event.key=='Enter')unlock()"><p id="pe" class="red"></p><button style="width:100%" onclick="unlock()">دخول</button></div>`;setTimeout(()=>$('#pw').focus(),50)}
async function unlock(){if(await sha(fv('pw'))==D.s.pin)$('#lk').innerHTML='';else{$('#pe').textContent='الرمز غير صحيح';$('#pw').value=''}}
async function setPin(rm){if(D.s.pin&&await sha(fv('pw0'))!=D.s.pin)return alert('الرمز الحالي غير صحيح');if(rm){D.s.pin='';sv();return draw()}const n=fv('pw1');if(n.length<4)return alert('الرمز 4 أرقام على الأقل');D.s.pin=await sha(n);sv();alert('تم حفظ الرمز');draw()}
let hid=0;document.addEventListener('visibilitychange',()=>{if(document.hidden)hid=Date.now();else if(D.s.pin&&hid&&Date.now()-hid>12e4)lock()});
SW.sec=()=>`<div class="cd"><b>رمز الدخول</b><p class="m">${D.s.pin?'الرمز مفعّل.':'لا يوجد رمز حاليًا.'} يمنع غيرك من فتح النظام على هذا الجوال، ويُطلب بعد فتح التطبيق وبعد غيابه دقيقتين. إذا نسيته فلا يمكن استرجاعه، فاحتفظ بنسخة احتياطية.</p>${D.s.pin?fl('الرمز الحالي','pw0','','password'):''}${fl('الرمز الجديد (4 أرقام أو أكثر)','pw1','','password')}<div class="row"><button onclick="setPin()">${D.s.pin?'تغيير الرمز':'تفعيل الرمز'}</button>${D.s.pin?'<button class="s" onclick="lock()">قفل الآن</button><button class="d" onclick="setPin(1)">إلغاء الرمز</button>':''}</div></div>`;
V.set=()=>A.sub?back('الإعدادات')+SW[A.sub]():tiles([['prof','الملف الشخصي','👤'],['org','بيانات المؤسسة','🏢'],['look','المظهر والخط','🎨'],['invs','الفواتير','🧾'],['lists','الفئات والوحدات','🗂'],['alr','التنبيهات','🔔'],['sec','رمز الدخول','🔒'],['bk','نسخة احتياطية','💾']]);
W.log=()=>`<h2>سجل العمليات</h2><div class="sc"><table><tr><th>الوقت</th><th>المستخدم</th><th>العملية</th></tr>${D.L.slice(0,200).map(l=>`<tr><td>${dt(l.ts)}</td><td>${l.u}</td><td>${E(l.a)}</td></tr>`).join('')}</table></div>`;
draw();lock();
